public int findLargestSubstring(Collection<String> strings) {
    int maxSubstringLength = 0;
    for (String str : strings) {
        for (int len = 1; len <= str.length() / 2; len++) {
            for (int i = 0; i <= str.length() - len; i++) {
                String substring = str.substring(i, i + len);
                if (strings.contains(substring) || strings.contains(substring.reverse())) {
                    maxSubstringLength = Math.max(maxSubstringLength, len);
                    break;
                }
            }
        }
    }
    return maxSubstringLength;
}

