public static int maxRegions(int N) {
    // Base cases
    if (N == 0) return 0;
    if (N == 1) return 1;
    if (N == 2) return 8;

    // Recursive case: the number of regions is the sum of the maximum regions of the remaining triangles minus the number of edges
    return (N * (N - 1) / 2) + (N - 2);
}

