    int count = 0;
    for (int num : numbers) {
        if (countMap.containsKey(num * 2)) {
            count++;
            countMap.put(num * 2, countMap.get(num * 2) + 1);
        } else {
            countMap.put(num, 1);
        }
    }
    return count;
}

