public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    boolean[][] visited = new boolean[n][n];
    int[][] direction = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
    Queue<int[]> queue = new LinkedList<>();
    queue.offer(start);

    while (!queue.isEmpty()) {
        int[] current = queue.poll();
        if (Arrays.equals(current, end)) {
            return "can be travelled";
        }

        for (int[] dir : direction) {
            int nx = current[0] + dir[0];
            int ny = current[1] + dir[1];
            if (nx >= 0 && nx < n && ny >= 0 && ny < n && !visited[nx][ny] && Arrays.stream(paths).anyMatch(path -> path[0] == current[0] && path[1] == current[1])) {
                queue.offer(new int[]{nx, ny});
                visited[nx][ny] = true;
            }
        }
    }

    return "cannot be travelled";
}

