public double trimMean(int[] arr) {
    // Filter out the smallest and largest 5% to avoid Edge Cases
    Arrays.sort(arr);
    int start = (int) (arr.length * 0.05);
    int end = (int) (arr.length * 0.95) - 1;
    int totalCount = end - start + 1;

    double sum = 0;
    for (int i = start; i <= end; i++) {
        sum += arr[i];
    }

    // Calculate the mean with an error within 10^-5
    double mean = sum / totalCount;
    return mean;
}

