public double trimMean(int[] arr) {
    // Sort the array in ascending order
    Arrays.sort(arr);

    // Calculate the number of elements to remove
    int numToRemove = (int) (0.05 * arr.length);

    // Calculate the sum of the elements to remove
    int sumToRemove = 0;
    for (int i = 0; i < numToRemove; i++) {
        sumToRemove += arr[i];
    }

    // Calculate the sum of the remaining elements
    int sumRemaining = 0;
    for (int i = numToRemove; i < arr.length - numToRemove; i++) {
        sumRemaining += arr[i];
    }

    // Calculate the trimmed mean
    return (double) sumRemaining / (arr.length - 2 * numToRemove);
}

