public boolean canArrange(int[] arr, int k) {
    int n = arr.length;
    // If n is odd, it is impossible to form n/2 pairs
    if (n % 2 != 0) {
        return false;
    }

    // Dictionary to store the count of remainders when each number is divided by k
    Map<Integer, Integer> remainderCount = new HashMap<>();

    // Count the remainder for each number in the array
    for (int num : arr) {
        int remainder = num % k;
        remainderCount.put(remainder, remainderCount.getOrDefault(remainder, 0) + 1);
    }

    // Iterate through the map and count pairs
    boolean canFormPairs = true;
    for (int remainder : remainderCount.keySet()) {
        if (remainder == 0 || remainder == k / 2) {
            // If remainder is 0 or remainder is k/2, check if there is an even number of such remainders
            if (remainderCount.get(remainder) % 2 != 0) {
                canFormPairs = false;
                break;
            }
        } else {
            // If remainder is other than 0 or k/2, the number of pairs for remainder must match the number of pairs for k - remainder
            if (remainderCount.get(remainder) != remainderCount.get(k - remainder)) {
                canFormPairs = false;
                break;
            }
        }
    }

    return canFormPairs;
}

