public int minInsertions(String s) {
        // Initialize two variables to keep track of the minimum number of insertions needed for left and right brackets
        int left = 0;
        int right = 0;

        // Iterate through each character in the string
        for (char c : s.toCharArray()) {
            if (c == '(') {
                // If the character is a left bracket, increment the left pointer
                left++;
            } else {
                // If the character is a right bracket
                if (left == 0) {
                    // If left pointers are zero, it means right bracket is unbalanced
                    right++; // Increment the right pointer
                } else {
                    // If left pointers are not zero, decrement the left pointer
                    left--; // Decrement the left pointer
                }
            }
        }

        // The minimum number of insertions required is the sum of left and right pointers
        return left + right;
    }

