public int maxUniqueSplit(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }

    int[] dp = new int[s.length() + 1];
    Arrays.fill(dp, 0);

    for (int i = 1; i <= s.length(); i++) {
        int maxUnique = 0;
        for (int j = i - 1; j >= 0; j--) {
            if (!set.contains(s.substring(j, i))) {
                set.add(s.substring(j, i));
                maxUnique = Math.max(maxUnique, 1 + dp[j]);
            }
        }
        dp[i] = maxUnique;
    }

    return dp[s.length()];
}

