public static int squarePermutations(int[] A) {
    Map<Integer, Integer> frequencyMap = new HashMap<>();
    for (int num : A) {
        frequencyMap.put(num, frequencyMap.getOrDefault(num, 0) + 1);
    }

    if (frequencyMap.containsKey(1) && frequencyMap.get(1) == 1) {
        return frequencyMap.get(1); // Single 1 appears only once, thus there is 1 permutation
    }

    int count = 1;
    for (Map.Entry<Integer, Integer> entry : frequencyMap.entrySet()) {
        int num = entry.getKey();
        int frequency = entry.getValue();
        if (frequency % 4 == 1 || frequency == 2) {
            count *= frequency;
        } else if (frequency % 8 == 6 || frequency == 8) {
            continue;
        }
    }

    return count;
}

