public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return new int[0];
    }

    int rows = mat.length;
    int cols = mat[0].length;
    boolean down = true;
    int[] result = new int[rows * cols];
    int row = 0;
    int col = 0;

    for (int i = 0; i < rows * cols; i++) {
        result[i] = mat[row][col];
        if (down) {
            // Move down
            if (col == cols - 1 || row == 0) {
                down = false;
                row++;
            } else {
                row--;
                col++;
            }
        } else {
            // Move up
            if (col == 0 || row == rows - 1) {
                down = true;
                col++;
            } else {
                row++;
                col--;
            }
        }
    }

    return result;
}

