public static int findSmallestInteger(int n) {
    if (n == 0) return -1;

    String numStr = String.valueOf(n);
    char[] characters = numStr.toCharArray();
    int len = characters.length;

    // Iterate through the string in reverse to find the largest digit that is less than the last digit
    for (int i = len - 2; i >= 0; i--) {
        if (characters[i] < characters[len - 1]) {
            // Swap characters i and len-1
            char temp = characters[i];
            characters[i] = characters[len - 1];
            characters[len - 1] = temp;

            // Reverse the substring after index i+1
            Arrays.sort(characters, i + 1, len);
            break;
        }
    }

    // Convert the modified string back to an integer
    try {
        return Integer.parseInt(new String(characters));
    } catch (NumberFormatException e) {
        return -1; // If the string cannot be parsed to an integer
    }
}

