public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    int current = 1;

    for (int i = 0; i < n; i++) {
        result.add(current);

        // Check if the next digit is a valid number (1-9)
        if (current % 10 < 9) {
            current *= 10;
        } else {
            // Move to the next higher digit
            current++;
            // Adjust if moving further leads to exceeding the range
            while (current % 10 != 0 && current > n) {
                current /= 10;
            }
        }
    }

    return result;
}

